/** The d.ts that types t() keys from the English files (namespace file names). */
export function typesSource(files: string[]): string {
  const ns = files.map(f => f.replace(/\.json$/, '')).sort()
  const ident = (n: string) => `ns_${n.replace(/[^A-Za-z0-9]/g, '_')}`
  const prop = (n: string) => (/^[A-Za-z_]\w*$/.test(n) ? n : `'${n}'`)
  return [
    '// Generated by `npm run i18n:types` from src/i18n/locales/en/*.json -- do not edit.',
    "import 'i18next'",
    ...ns.map(n => `import type ${ident(n)} from './locales/en/${n}.json'`),
    '',
    "declare module 'i18next' {",
    '  interface CustomTypeOptions {',
    "    defaultNS: 'common'",
    '    resources: {',
    ...ns.map(n => `      ${prop(n)}: typeof ${ident(n)}`),
    '    }',
    '  }',
    '}',
    '',
  ].join('\n')
}
